@HasDerivAt.unique : ∀ {𝕜 : Type u} [inst : NontriviallyNormedField.{u} 𝕜] {F : Type v} [inst_1 : NormedAddCommGroup.{v} F]
  [inst_2 : NormedSpace.{u, v} 𝕜 F] {f : 𝕜 → F} {f₀' f₁' : F} {x : 𝕜},
  HasDerivAt.{u, v} f f₀' x → HasDerivAt.{u, v} f f₁' x → Eq.{v + 1} f₀' f₁'

@hasDerivAt_pi : ∀ {𝕜 : Type u} [inst : NontriviallyNormedField.{u} 𝕜] {x : 𝕜} {ι : Type u_1} {E' : ι → Type u_2}
  [inst_1 : (i : ι) → NormedAddCommGroup.{u_2} (E' i)] [inst_2 : (i : ι) → NormedSpace.{u, u_2} 𝕜 (E' i)]
  {φ : 𝕜 → (i : ι) → E' i} {φ' : (i : ι) → E' i},
  HasDerivAt.{u, max u_1 u_2} φ φ' x ↔ ∀ (i : ι), HasDerivAt.{u, u_2} (fun x => φ x i) (φ' i) x

@HasDerivAt.congr_of_eventuallyEq : ∀ {𝕜 : Type u} [inst : NontriviallyNormedField.{u} 𝕜] {F : Type v} [inst_1 : NormedAddCommGroup.{v} F]
  [inst_2 : NormedSpace.{u, v} 𝕜 F] {f f₁ : 𝕜 → F} {f' : F} {x : 𝕜},
  HasDerivAt.{u, v} f f' x → Filter.EventuallyEq.{u, v} (nhds.{u} x) f₁ f → HasDerivAt.{u, v} f₁ f' x
